text:
certificate-check {
  display: grid;
  grid-template-columns: fit-content(0);
  flex-direction: column;
  gap: 4px;
  margin-inline: 8px;
  font-size: 1rem;

  #useSecureConnectionValue > & {
    margin: 4px 0;
  }

  & > img {
    grid-column: 1;
    content: "";
    inline-size: 16px;
    block-size: 16px;
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
  }

  & > span {
    grid-column: 2;
  }

  & > div {
    grid-column: 2;
    display: flex;
    gap: 4px;
    align-items: center;
  }
